"""Shared constants for the Mantle hooks runtime and authoring surface."""

from __future__ import annotations

# ---------------------------------------------------------------------------
# Project snapshot layout
# ---------------------------------------------------------------------------

HOOKS_FILE_NAME = "hooks.py"
HOOKS_DIR_NAME = "hooks"

# ---------------------------------------------------------------------------
# Decorator metadata (function attributes)
# ---------------------------------------------------------------------------

HOOK_POINT_ATTR = "_hook_point"
HOOK_LANE_ATTR = "_hook_lane"
HOOK_TIMEOUT_MS_ATTR = "_hook_timeout_ms"

# ---------------------------------------------------------------------------
# Lanes and fail policies
# ---------------------------------------------------------------------------

LANE_OBSERVE = "observe"
LANE_MODIFY = "modify"

FAIL_OPEN = "open"
FAIL_CLOSED = "closed"

# ---------------------------------------------------------------------------
# Timeouts (milliseconds)
# ---------------------------------------------------------------------------

DEFAULT_OBSERVE_TIMEOUT_MS = 100
DEFAULT_MODIFY_TIMEOUT_MS = 500

# Tracker metadata written when a text hook prevents an utterance from entering
# the engine. History projections must use this same key to avoid replaying it.
DISCARDED_EVENT_METADATA_KEY = "discarded"

# Packaged in ``default_skills/default_responses.yml``; builders may override.
UTTER_INCOMING_MESSAGE_REJECTED = "utter_incoming_message_rejected"
UTTER_OUTGOING_TEXT_REJECTED = "utter_outgoing_text_rejected"

# ---------------------------------------------------------------------------
# Operational logging
# ---------------------------------------------------------------------------

LOG_HOOK_EXECUTION = "mantle.hooks.execution"
LOG_OBSERVER_CONTROL_FLOW_DISCARDED = "mantle.hooks.observer.control_flow_discarded"
LOG_MODIFY_CONTROL_FLOW_DISCARDED = "mantle.hooks.modify.control_flow_discarded"
LOG_OBSERVER_TIMEOUT = "mantle.hooks.observer.timeout"
LOG_OBSERVER_ERROR = "mantle.hooks.observer.error"

# ---------------------------------------------------------------------------
# Insertion point names
# ---------------------------------------------------------------------------

POINT_TURN_STARTED = "turn_started"
POINT_TURN_FINISHED = "turn_finished"
POINT_INCOMING_MESSAGE = "incoming_message"
POINT_MODEL_REQUEST = "model_request"
POINT_MODEL_RESPONSE = "model_response"
POINT_TOOL_CALL = "tool_call"
POINT_TOOL_RESULT = "tool_result"
POINT_KNOWLEDGE_QUERY = "knowledge_query"
POINT_KNOWLEDGE_RESULTS = "knowledge_results"
POINT_OUTGOING_TEXT = "outgoing_text"

OBSERVE_ONLY_POINTS = frozenset({POINT_TURN_STARTED, POINT_TURN_FINISHED})

# One ``modify_tool_call`` registration may be invoked once per tool call in
# an LLM batch. Invoke those calls sequentially in batch order and finish
# the full preflight pass before any tool runs. Parallel preflight is
# intentionally out of scope for the first tool-call wiring.
TOOL_CALL_PREFLIGHT_MODE = "sequential_before_dispatch"

# ``RetryModel.feedback`` placement for model-response / tool-call steering:
# inject into the next model request only (turn-local system note).
RETRY_MODEL_FEEDBACK_DESTINATION = "next_model_request_system_note"

ALL_POINT_NAMES = frozenset(
    {
        POINT_TURN_STARTED,
        POINT_TURN_FINISHED,
        POINT_INCOMING_MESSAGE,
        POINT_MODEL_REQUEST,
        POINT_MODEL_RESPONSE,
        POINT_TOOL_CALL,
        POINT_TOOL_RESULT,
        POINT_KNOWLEDGE_QUERY,
        POINT_KNOWLEDGE_RESULTS,
        POINT_OUTGOING_TEXT,
    }
)


def observe_decorator_name(point: str) -> str:
    """Return the public ``on_*`` decorator name for *point*."""
    return f"on_{point}"


def modify_decorator_name(point: str) -> str | None:
    """Return the public ``modify_*`` decorator name, or ``None`` when absent."""
    if point in OBSERVE_ONLY_POINTS:
        return None
    return f"modify_{point}"
